def check_callback_url(url: str):
    """
    Reject callback URLs whose origin (scheme://host[:port]) is not fully matched
    by at least one of `lnbits_callback_url_rules`. No rules means any http(s) URL.
    """
    try:
        parsed = urlparse(url)
        hostname = parsed.hostname
        parsed.port  # noqa: B018 - raises ValueError on an invalid port
    except ValueError as exc:
        raise ValueError("Callback URL is not allowed.") from exc

    # userinfo ("user@host") is rejected: it can disguise the real target host.
    if parsed.scheme not in ("http", "https") or not hostname or "@" in parsed.netloc:
        raise ValueError("Callback URL is not allowed.")

    if not settings.lnbits_callback_url_rules:
        return

    origin = f"{parsed.scheme}://{parsed.netloc}"
    for rule in settings.lnbits_callback_url_rules:
        if re.fullmatch(rule, origin) is not None:
            return
    raise ValueError(f"Callback URL origin '{origin}' is not allowed.")

